for(let e of document.querySelectorAll('[role="tablist"]')){let t=e.querySelectorAll('[role="tab"]');for(let e of t)e.tabIndex=-1,e.onfocus=o=>{let l=[...t].find(e=>0===e.tabIndex);l&&(l.tabIndex=-1),e.tabIndex=0};t[0].tabIndex=0,e.onkeydown=e=>{switch(e.key){case"ArrowRight":{let o=[...t].indexOf(document.activeElement),l=t[o+1];l&&(e.preventDefault(),l.focus(),l.click());break}case"ArrowLeft":{let o=[...t].indexOf(document.activeElement),l=t[o-1];l&&(e.preventDefault(),l.focus(),l.click())}}}}for(let e of document.querySelectorAll('[role="radiogroup"]')){let t=e.querySelectorAll('[role="radio"]');for(let e of t)e.tabIndex=-1,e.onfocus=o=>{let l=[...t].find(e=>0===e.tabIndex);l&&(l.tabIndex=-1),e.tabIndex=0};t[0].tabIndex=0,e.onkeydown=e=>{switch(e.key){case"ArrowDown":{let o=[...t].indexOf(document.activeElement),l=t[o+1];l&&(e.preventDefault(),l.focus(),l.click());break}case"ArrowUp":{let o=[...t].indexOf(document.activeElement),l=t[o-1];l&&(e.preventDefault(),l.focus(),l.click())}}}}